-- Booking status machine. Allowed moves: PENDING -> CONFIRMED | CANCELLED | EXPIRED, CONFIRMED -> COMPLETED | CANCELLED | NO_SHOW.
-- Every other status is final. The product of a booking can never change.
CREATE FUNCTION bookings_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.product IS DISTINCT FROM OLD.product THEN RAISE EXCEPTION 'booking product cannot be changed'; END IF;
  IF NEW.supplier_id IS DISTINCT FROM OLD.supplier_id THEN RAISE EXCEPTION 'booking supplier cannot be changed'; END IF;
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NOT ((OLD.status = 'PENDING' AND NEW.status IN ('CONFIRMED', 'CANCELLED', 'EXPIRED'))
         OR (OLD.status = 'CONFIRMED' AND NEW.status IN ('COMPLETED', 'CANCELLED', 'NO_SHOW'))) THEN
      RAISE EXCEPTION 'illegal booking status change % -> %', OLD.status, NEW.status USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER bookings_guard BEFORE UPDATE ON "bookings" FOR EACH ROW EXECUTE FUNCTION bookings_guard();

-- A hotel item can only hang off a HOTEL booking, a trip item off a TRIP booking, and so on.
CREATE FUNCTION booking_item_product_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE p "BookingProduct";
BEGIN
  SELECT product INTO p FROM bookings WHERE id = NEW.booking_id;
  IF p IS DISTINCT FROM TG_ARGV[0]::"BookingProduct" THEN
    RAISE EXCEPTION '% rows can only belong to % bookings', TG_TABLE_NAME, TG_ARGV[0] USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER hotel_booking_items_product BEFORE INSERT OR UPDATE OF booking_id ON "hotel_booking_items" FOR EACH ROW EXECUTE FUNCTION booking_item_product_guard('HOTEL');
CREATE TRIGGER trip_booking_items_product BEFORE INSERT OR UPDATE OF booking_id ON "trip_booking_items" FOR EACH ROW EXECUTE FUNCTION booking_item_product_guard('TRIP');
CREATE TRIGGER transport_booking_items_product BEFORE INSERT OR UPDATE OF booking_id ON "transport_booking_items" FOR EACH ROW EXECUTE FUNCTION booking_item_product_guard('TRANSPORT');
CREATE TRIGGER club_booking_items_product BEFORE INSERT OR UPDATE OF booking_id ON "club_booking_items" FOR EACH ROW EXECUTE FUNCTION booking_item_product_guard('CLUB');

-- A refund must point at a successful payment of the same booking and can never exceed it.
CREATE FUNCTION payments_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE orig payments%ROWTYPE; refunded numeric;
BEGIN
  IF NEW.kind = 'REFUND' THEN
    SELECT * INTO orig FROM payments WHERE id = NEW.refund_of_id;
    IF orig.id IS NULL OR orig.booking_id <> NEW.booking_id OR orig.kind <> 'PAYMENT' OR orig.tx_status <> 'SUCCEEDED' THEN
      RAISE EXCEPTION 'a refund must point at a successful payment of the same booking' USING ERRCODE = '23514';
    END IF;
    SELECT COALESCE(SUM(amount), 0) INTO refunded FROM payments
      WHERE refund_of_id = NEW.refund_of_id AND tx_status = 'SUCCEEDED' AND id <> NEW.id;
    IF NEW.tx_status = 'SUCCEEDED' AND refunded + NEW.amount > orig.amount THEN
      RAISE EXCEPTION 'refunds (%) would exceed the original payment (%)', refunded + NEW.amount, orig.amount USING ERRCODE = '23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER payments_guard BEFORE INSERT OR UPDATE ON "payments" FOR EACH ROW EXECUTE FUNCTION payments_guard();

-- bookings.paid_amount and payment_status are always derived from the payments, never typed in.
CREATE FUNCTION payments_sync() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE bid uuid; paid numeric; refunds numeric; tot numeric; ps "BookingPaymentStatus";
BEGIN
  IF TG_OP = 'DELETE' THEN bid := OLD.booking_id; ELSE bid := NEW.booking_id; END IF;
  SELECT COALESCE(SUM(amount) FILTER (WHERE kind = 'PAYMENT'), 0), COALESCE(SUM(amount) FILTER (WHERE kind = 'REFUND'), 0)
    INTO paid, refunds FROM payments WHERE booking_id = bid AND tx_status = 'SUCCEEDED';
  SELECT total_amount INTO tot FROM bookings WHERE id = bid;
  IF refunds > 0 AND paid - refunds <= 0 THEN ps := 'REFUNDED';
  ELSIF refunds > 0 THEN ps := 'PARTIALLY_REFUNDED';
  ELSIF paid <= 0 THEN ps := 'UNPAID';
  ELSIF paid >= tot THEN ps := 'PAID';
  ELSE ps := 'PARTIAL'; END IF;
  UPDATE bookings SET paid_amount = paid - refunds, payment_status = ps, updated_at = CURRENT_TIMESTAMP WHERE id = bid;
  RETURN NULL;
END $$;
CREATE TRIGGER payments_sync AFTER INSERT OR UPDATE OR DELETE ON "payments" FOR EACH ROW EXECUTE FUNCTION payments_sync();

-- The booking timeline and the per-supplier numbering are append-only history.
CREATE FUNCTION booking_events_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'booking_events is append-only'; END $$;
